  "summary": "The code contained critical path traversal vulnerabilities and lacked essential production-grade safeguards like directory validation and file size constants. The refactored code implements path sanitization, directory initialization, and improved stream error handling to ensure robust and secure file operations.",
  "fixed_code": "const express = require('express');\nconst fs = require('fs');\nconst path = require('path');\n\nconst app = express();\nconst UPLOADS = path.join(__dirname, 'uploads');\nconst MAX_FILE_SIZE = 10 * 1024 * 1024;\n\nif (!fs.existsSync(UPLOADS)) {\n    fs.mkdirSync(UPLOADS, { recursive: true });\n}\n\n/**\n * Handles file uploads via PUT requests.\n * @param {string} name - The target filename.\n */\napp.put('/upload/:name', (req, res) => {\n    const contentLength = Number(req.headers['content-length']);\n    if (isNaN(contentLength) || contentLength > MAX_FILE_SIZE) {\n        return res.sendStatus(413);\n    }\n\n    const safeName = path.basename(req.params.name);\n    const dest = path.join(UPLOADS, safeName);\n\n    const writeStream = fs.createWriteStream(dest);\n    \n    req.pipe(writeStream);\n\n    writeStream.on('finish', () => res.sendStatus(201));\n    writeStream.on('error', (err) => {\n        console.error(err);\n        res.sendStatus(500);\n    });\n\n    req.on('close', () => {\n        if (!writeStream.writableEnded) {\n            writeStream.destroy();\n        }\n    });\n});\n\napp.listen(3000);"
}
